/* ============================================================================
Revision v0.2R7 correction
- Adds the four governed policy-boundary columns to the session-scoped
  `_m2_1_vctx` validation projection.
- Adds an explicit context-projection guard before the 112 positive controls.
- Does not alter any positive-control code, threshold, Boolean methodology,
  generated business row, routing result, contract row, archive row, set
  hash, lifecycle rule, or accepted predecessor record.
============================================================================ */

/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
M2.1 — Eligibility, Policy Gates & Decision Routing Foundations

Program : 135_msbf_m2_1_eligibility_policy_routing_validation_v0_2R7.sql
Version : v0.2R7
Title   : End-to-End Positive Validation

Purpose
Validate the accepted G2 source, M2.1 policy/reference definitions, all gate outcomes, routing priority, matched stress non-improvement, latest/archive reproduction, deterministic hashes and strict stage boundaries.

Inputs
Persisted M2.1 generated outputs and accepted G2 contracts.

Outputs
One session-preserved filterable table containing 112 governed positive controls and lifecycle advancement only when all pass.

Stage boundary
Validation is read-only with respect to business rows. It may refresh M2.1 positive evidence and lifecycle status.

Execution standard
Run the complete file with DBeaver Execute SQL Script. Stop at the first
PostgreSQL error. Never use Retry, Skip or Skip All. Execute ROLLBACK after a
failed transactional program.
============================================================================ */

BEGIN;
SET LOCAL work_mem='96MB';
SET LOCAL statement_timeout='25min';
SET LOCAL jit=off;

DROP TABLE IF EXISTS _m2_1_vctx;
CREATE TEMP TABLE _m2_1_vctx ON COMMIT DROP AS
SELECT
 r.run_id,r.run_status,p.policy_status,p.methodology_version,p.contract_code,p.contract_version,
 p.schema_version,p.configuration_payload,
 p.synthetic_data_only_flag,
 p.no_final_offer_terms_flag,
 p.no_production_adverse_action_flag,
 p.acquisition_source_review_only_flag,
 p.configuration_hash AS policy_configuration_hash,
 g.bundle_status AS source_g2_status,g.combined_g2_hash AS source_g2_combined_hash,
 g.source_m1_15_combined_hash AS source_m1_15_hash,g.source_m1_16_combined_hash AS source_m1_16_hash,
 g.accepted_scenario_set_hash,
 (SELECT result_status FROM msbf_ctl.acceptance_gate_result WHERE run_id=r.run_id AND gate_id='G2_M1_CONTRACT' ORDER BY review_version DESC LIMIT 1) AS g2_gate_status,
 c.contract_status
FROM msbf_ctl.run_registry r
JOIN msbf_ctl.m1_17_g2_bundle_registry g ON g.module1_run_id=r.run_id
JOIN msbf_ctl.m2_1_strategy_contract_registry c ON c.module1_run_id=r.run_id
CROSS JOIN msbf_ctl.m2_1_policy_profile p
WHERE r.run_code='M1_V0_2_BASELINE_BUILD' AND r.run_version=1 AND p.policy_code='M2_1_ELIGIBILITY_POLICY_V1';

DO $m2_1_context_projection_guard$
DECLARE
    v record;
BEGIN
    SELECT *
    INTO v
    FROM _m2_1_vctx;

    IF v.run_id IS NULL
       OR v.synthetic_data_only_flag IS DISTINCT FROM TRUE
       OR v.no_final_offer_terms_flag IS DISTINCT FROM TRUE
       OR v.no_production_adverse_action_flag IS DISTINCT FROM TRUE
       OR v.acquisition_source_review_only_flag IS DISTINCT FROM TRUE
       OR (v.configuration_payload->>'synthetic_data_only')::boolean
            IS DISTINCT FROM v.synthetic_data_only_flag
       OR (v.configuration_payload->>'no_final_offer_terms')::boolean
            IS DISTINCT FROM v.no_final_offer_terms_flag
       OR (v.configuration_payload->>'no_production_adverse_action')::boolean
            IS DISTINCT FROM v.no_production_adverse_action_flag
       OR (v.configuration_payload->>'acquisition_source_review_only')::boolean
            IS DISTINCT FROM v.acquisition_source_review_only_flag THEN
        RAISE EXCEPTION
            'M2.1 v0.2R7 validation context projection failed: %',
            row_to_json(v);
    END IF;
END;
$m2_1_context_projection_guard$;

DO $m2_1_validation_ready$
BEGIN PERFORM msbf_ctl.m2_1_assert_validation_ready((SELECT run_id FROM _m2_1_vctx)); END;
$m2_1_validation_ready$;

DROP TABLE IF EXISTS _m2_1_vg2;
CREATE TEMP TABLE _m2_1_vg2 ON COMMIT DROP AS
SELECT * FROM msbf_m1.v_m1_17_g2_integrated_consumption WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
CREATE UNIQUE INDEX ON _m2_1_vg2(scenario_id,merchant_application_id);
ANALYZE _m2_1_vg2;

DROP TABLE IF EXISTS _m2_1_vgate;
CREATE TEMP TABLE _m2_1_vgate ON COMMIT DROP AS
SELECT * FROM msbf_m2.application_policy_gate_result WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
CREATE UNIQUE INDEX ON _m2_1_vgate(scenario_id,merchant_application_id,gate_code);
ANALYZE _m2_1_vgate;

DROP TABLE IF EXISTS _m2_1_vsnapshot;
CREATE TEMP TABLE _m2_1_vsnapshot ON COMMIT DROP AS
SELECT * FROM msbf_m2.application_eligibility_routing_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
CREATE UNIQUE INDEX ON _m2_1_vsnapshot(scenario_id,merchant_application_id);
ANALYZE _m2_1_vsnapshot;

DROP TABLE IF EXISTS _m2_1_vlatest;
CREATE TEMP TABLE _m2_1_vlatest ON COMMIT DROP AS
SELECT * FROM msbf_m2.application_eligibility_routing_latest WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
CREATE UNIQUE INDEX ON _m2_1_vlatest(scenario_id,merchant_application_id);
ANALYZE _m2_1_vlatest;

DROP TABLE IF EXISTS _m2_1_varchive;
CREATE TEMP TABLE _m2_1_varchive ON COMMIT DROP AS
SELECT * FROM msbf_m2.application_eligibility_routing_archive WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
CREATE UNIQUE INDEX ON _m2_1_varchive(scenario_id,merchant_application_id);
ANALYZE _m2_1_varchive;

DROP TABLE IF EXISTS _m2_1_vcanonical;
CREATE TEMP TABLE _m2_1_vcanonical(entity_type text,entity_key text,row_hash text) ON COMMIT DROP;
INSERT INTO _m2_1_vcanonical SELECT 'CAMPAIGN',strategy_campaign_code||'|v'||strategy_campaign_version,row_hash FROM msbf_m2.strategy_campaign WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
INSERT INTO _m2_1_vcanonical SELECT 'GATE_DEFINITION',gate_code,row_hash FROM msbf_m2.policy_gate_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
INSERT INTO _m2_1_vcanonical SELECT 'REASON_CODE',reason_code,row_hash FROM msbf_m2.reason_code_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
INSERT INTO _m2_1_vcanonical SELECT 'OUTCOME',route_code,row_hash FROM msbf_m2.routing_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
INSERT INTO _m2_1_vcanonical SELECT 'GATE_RESULT',scenario_id||'|'||merchant_application_id||'|'||gate_code,row_hash FROM _m2_1_vgate;
INSERT INTO _m2_1_vcanonical SELECT 'ROUTING_SNAPSHOT',scenario_id||'|'||merchant_application_id,row_hash FROM _m2_1_vsnapshot;
INSERT INTO _m2_1_vcanonical SELECT 'LATEST',scenario_id||'|'||merchant_application_id,contract_row_hash FROM _m2_1_vlatest;
INSERT INTO _m2_1_vcanonical SELECT 'ARCHIVE',scenario_id||'|'||merchant_application_id,archive_row_hash FROM _m2_1_varchive;
INSERT INTO _m2_1_vcanonical SELECT 'REGISTRY',contract_code||'|v'||contract_version,row_hash FROM msbf_ctl.m2_1_strategy_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
CREATE UNIQUE INDEX ON _m2_1_vcanonical(entity_type,entity_key);
ANALYZE _m2_1_vcanonical;

DROP TABLE IF EXISTS _m2_1_validation;
CREATE TEMP TABLE _m2_1_validation(
 evidence_code text PRIMARY KEY,metric_name text NOT NULL,observed_value text,
 threshold_value text,status text NOT NULL,interpretation text NOT NULL
) ON COMMIT PRESERVE ROWS;

CREATE OR REPLACE FUNCTION pg_temp.m2_1_add_check(p_code text,p_name text,p_observed text,p_threshold text,p_pass boolean,p_interpretation text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 INSERT INTO _m2_1_validation VALUES(p_code,p_name,p_observed,p_threshold,CASE WHEN p_pass THEN 'PASS' ELSE 'FAIL' END,p_interpretation);
END; $$;

DO $m2_1_checks$
BEGIN
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_001_RUN_STATUS','Run lifecycle',((SELECT run_status FROM _m2_1_vctx))::text,'M2_1_GENERATED_OR_VALIDATED',coalesce(((SELECT run_status IN ('M2_1_GENERATED','M2_1_VALIDATED') FROM _m2_1_vctx)),false),'Validation is safely rerunnable at GENERATED or VALIDATED state.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_002_POLICY_APPROVED','Policy approval and stage-boundary flags',((SELECT concat_ws('|',policy_status,synthetic_data_only_flag,no_final_offer_terms_flag,no_production_adverse_action_flag,acquisition_source_review_only_flag) FROM _m2_1_vctx))::text,'APPROVED|true|true|true|true',coalesce(((SELECT policy_status='APPROVED' AND synthetic_data_only_flag AND no_final_offer_terms_flag AND no_production_adverse_action_flag AND acquisition_source_review_only_flag AND (configuration_payload->>'synthetic_data_only')::boolean IS NOT DISTINCT FROM synthetic_data_only_flag AND (configuration_payload->>'no_final_offer_terms')::boolean IS NOT DISTINCT FROM no_final_offer_terms_flag AND (configuration_payload->>'no_production_adverse_action')::boolean IS NOT DISTINCT FROM no_production_adverse_action_flag AND (configuration_payload->>'acquisition_source_review_only')::boolean IS NOT DISTINCT FROM acquisition_source_review_only_flag FROM _m2_1_vctx)),false),'M2.1 policy approval and all four physical stage-boundary flags match the governed configuration payload.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_003_POLICY_HASH','Policy hash identity',((SELECT policy_configuration_hash FROM _m2_1_vctx))::text,'RECONSTRUCTED',coalesce(((SELECT policy_configuration_hash=msbf_ctl.m2_1_hash_jsonb(configuration_payload) FROM _m2_1_vctx)),false),'Policy hash reconstructs from persisted payload.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_004_METHOD','Methodology identity',((SELECT methodology_version FROM _m2_1_vctx))::text,'M2_1_METHOD_V1',coalesce(((SELECT methodology_version='M2_1_METHOD_V1' FROM _m2_1_vctx)),false),'Methodology is exact.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_005_CONTRACT_CODE','Contract identity',((SELECT contract_code FROM _m2_1_vctx))::text,'M2_ELIGIBILITY_ROUTING_CONSUMPTION',coalesce(((SELECT contract_code='M2_ELIGIBILITY_ROUTING_CONSUMPTION' FROM _m2_1_vctx)),false),'Contract code is exact.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_006_SCHEMA_VERSION','Schema identity',((SELECT schema_version FROM _m2_1_vctx))::text,'M2_1_ROUTING_SCHEMA_V1',coalesce(((SELECT schema_version='M2_1_ROUTING_SCHEMA_V1' FROM _m2_1_vctx)),false),'Schema version is exact.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_007_SOURCE_G2_STATUS','G2 lifecycle',((SELECT source_g2_status FROM _m2_1_vctx))::text,'ACCEPTED',coalesce(((SELECT source_g2_status='ACCEPTED' FROM _m2_1_vctx)),false),'Source G2 bundle remains accepted.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_008_SOURCE_G2_HASH','G2 combined hash',((SELECT source_g2_combined_hash FROM _m2_1_vctx))::text,'7d9e466da28cad2551aa99c4c40c912b',coalesce(((SELECT source_g2_combined_hash='7d9e466da28cad2551aa99c4c40c912b' FROM _m2_1_vctx)),false),'Source G2 hash is unchanged.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_009_G2_GATE','G2 acceptance gate',((SELECT g2_gate_status FROM _m2_1_vctx))::text,'PASS',coalesce(((SELECT g2_gate_status='PASS' FROM _m2_1_vctx)),false),'G2_M1_CONTRACT remains PASS.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_010_M1_15_HASH','M1.15 source identity',((SELECT source_m1_15_hash FROM _m2_1_vctx))::text,'fcd2704e17ec0d2e73191ea36061d74b',coalesce(((SELECT source_m1_15_hash='fcd2704e17ec0d2e73191ea36061d74b' FROM _m2_1_vctx)),false),'Accepted M1.15 identity remains unchanged.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_011_M1_16_HASH','M1.16 source identity',((SELECT source_m1_16_hash FROM _m2_1_vctx))::text,'86df51a0ca68d84096d00ff0f1b19f33',coalesce(((SELECT source_m1_16_hash='86df51a0ca68d84096d00ff0f1b19f33' FROM _m2_1_vctx)),false),'Accepted M1.16 identity remains unchanged.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_012_SCENARIO_SET','Scenario-set identity',((SELECT accepted_scenario_set_hash FROM _m2_1_vctx))::text,'3f85921bf6fc30ddc6cee146085e58c5',coalesce(((SELECT accepted_scenario_set_hash='3f85921bf6fc30ddc6cee146085e58c5' FROM _m2_1_vctx)),false),'Accepted scenario set is exact.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_013_INPUT_ROWS','G2 input rows',((SELECT count(*)::text FROM _m2_1_vg2))::text,'1500',coalesce(((SELECT count(*)=1500 FROM _m2_1_vg2)),false),'Exactly 1,500 G2 scenario/application rows.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_014_APPLICATIONS','Application count',((SELECT count(DISTINCT merchant_application_id)::text FROM _m2_1_vg2))::text,'750',coalesce(((SELECT count(DISTINCT merchant_application_id)=750 FROM _m2_1_vg2)),false),'Exactly 750 applications.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_015_SCENARIOS','Scenario count',((SELECT count(DISTINCT scenario_id)::text FROM _m2_1_vg2))::text,'2',coalesce(((SELECT count(DISTINCT scenario_id)=2 FROM _m2_1_vg2)),false),'Exactly two scenarios.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_016_BASELINE_ROWS','Baseline rows',((SELECT count(*)::text FROM _m2_1_vg2 WHERE scenario_code='BASELINE'))::text,'750',coalesce(((SELECT count(*)=750 FROM _m2_1_vg2 WHERE scenario_code='BASELINE')),false),'Exactly 750 baseline rows.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_017_STRESS_ROWS','Stress rows',((SELECT count(*)::text FROM _m2_1_vg2 WHERE scenario_code='RECESSION_ENERGY'))::text,'750',coalesce(((SELECT count(*)=750 FROM _m2_1_vg2 WHERE scenario_code='RECESSION_ENERGY')),false),'Exactly 750 stress rows.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_018_G2_GRAIN','G2 unique grain',((SELECT (count(*)-count(DISTINCT (scenario_id,merchant_application_id)))::text FROM _m2_1_vg2))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT (scenario_id,merchant_application_id)) FROM _m2_1_vg2)),false),'G2 scenario/application grain is unique.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_019_G2_HASH_LINEAGE','G2 row lineage',((SELECT count(*) FILTER(WHERE m1_15_contract_row_hash IS NULL OR m1_16_contract_row_hash IS NULL)::text FROM _m2_1_vg2))::text,'0',coalesce(((SELECT count(*) FILTER(WHERE m1_15_contract_row_hash IS NULL OR m1_16_contract_row_hash IS NULL)=0 FROM _m2_1_vg2)),false),'Every input row has both accepted source-contract hashes.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_020_G2_HASH_SHAPE','G2 source hash shape',((SELECT source_g2_combined_hash FROM _m2_1_vctx))::text,'32 lowercase hex',coalesce(((SELECT length(source_g2_combined_hash)=32 AND source_g2_combined_hash ~ '^[0-9a-f]+$' FROM _m2_1_vctx)),false),'G2 source hash has valid physical shape.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_021_CAMPAIGN_COUNT','Strategy campaign count',((SELECT count(*)::text FROM msbf_m2.strategy_campaign WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_m2.strategy_campaign WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'One approved baseline campaign.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_022_CAMPAIGN_APPROVED','Strategy campaign approval',((SELECT campaign_status FROM msbf_m2.strategy_campaign WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'APPROVED',coalesce(((SELECT campaign_status='APPROVED' FROM msbf_m2.strategy_campaign WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Campaign is approved.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_023_CAMPAIGN_HASH','Campaign row hash',((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(c)-'row_hash'-'created_at'))::text FROM msbf_m2.strategy_campaign c WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'0',coalesce(((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(c)-'row_hash'-'created_at'))=0 FROM msbf_m2.strategy_campaign c WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Campaign row hash reconstructs.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_024_GATE_DEFINITION_COUNT','Gate-definition count',((SELECT count(*)::text FROM msbf_m2.policy_gate_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'12',coalesce(((SELECT count(*)=12 FROM msbf_m2.policy_gate_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Twelve active gates exist.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_025_GATE_SEQUENCE','Gate sequence',((SELECT concat(min(gate_sequence),'|',max(gate_sequence),'|',count(DISTINCT gate_sequence)) FROM msbf_m2.policy_gate_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'1|12|12',coalesce(((SELECT min(gate_sequence)=1 AND max(gate_sequence)=12 AND count(DISTINCT gate_sequence)=12 FROM msbf_m2.policy_gate_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Gate order is complete and unique.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_026_GATE_HASHES','Gate-definition hashes',((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))::text FROM msbf_m2.policy_gate_definition d WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'0',coalesce(((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))=0 FROM msbf_m2.policy_gate_definition d WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Gate-definition hashes reconstruct.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_027_REASON_COUNT','Reason-code count',((SELECT count(*)::text FROM msbf_m2.reason_code_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'23',coalesce(((SELECT count(*)=23 FROM msbf_m2.reason_code_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Twenty-three transparent reason codes exist.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_028_REASON_NO_ADVERSE','No production adverse-action codes',((SELECT count(*) FILTER(WHERE production_adverse_action_flag)::text FROM msbf_m2.reason_code_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'0',coalesce(((SELECT count(*) FILTER(WHERE production_adverse_action_flag)=0 FROM msbf_m2.reason_code_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Reason codes are not production adverse-action notices.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_029_REASON_HASHES','Reason-code hashes',((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))::text FROM msbf_m2.reason_code_definition d WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'0',coalesce(((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))=0 FROM msbf_m2.reason_code_definition d WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Reason-code hashes reconstruct.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_030_OUTCOME_COUNT','Routing outcome count',((SELECT count(*)::text FROM msbf_m2.routing_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'4',coalesce(((SELECT count(*)=4 FROM msbf_m2.routing_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Four governed outcomes exist.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_031_OUTCOME_RANKS','Routing outcome ranks',((SELECT concat(min(route_rank),'|',max(route_rank),'|',count(DISTINCT route_rank)) FROM msbf_m2.routing_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'1|4|4',coalesce(((SELECT min(route_rank)=1 AND max(route_rank)=4 AND count(DISTINCT route_rank)=4 FROM msbf_m2.routing_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Outcome ranks are complete.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_032_OUTCOME_HASHES','Outcome hashes',((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))::text FROM msbf_m2.routing_outcome_definition d WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'0',coalesce(((SELECT count(*) FILTER(WHERE row_hash IS DISTINCT FROM msbf_ctl.m2_1_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))=0 FROM msbf_m2.routing_outcome_definition d WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Outcome hashes reconstruct.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_033_ACCEPTANCE_GATE_DEFINED','Acceptance gate catalog',((SELECT count(*)::text FROM msbf_ref.acceptance_gate_catalog WHERE gate_id='M2_1_ELIGIBILITY_POLICY_ROUTING' AND active_flag))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_ref.acceptance_gate_catalog WHERE gate_id='M2_1_ELIGIBILITY_POLICY_ROUTING' AND active_flag)),false),'M2.1 acceptance gate is defined.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_034_ARCHIVE_TRIGGER','Archive trigger',((SELECT count(*)::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='msbf_m2' AND c.relname='application_eligibility_routing_archive' AND NOT t.tgisinternal))::text,'1',coalesce(((SELECT count(*)=1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='msbf_m2' AND c.relname='application_eligibility_routing_archive' AND NOT t.tgisinternal)),false),'Immutable archive trigger exists.');
