    PERFORM pg_temp.m2_1_add_check('M2_1_POS_091_REGISTRY_HASH_SHAPE','Registry hash shapes',((SELECT count(*)::text FROM msbf_ctl.m2_1_strategy_contract_registry r CROSS JOIN LATERAL (VALUES(r.campaign_set_hash),(r.gate_definition_set_hash),(r.reason_code_set_hash),(r.outcome_definition_set_hash),(r.gate_result_set_hash),(r.routing_snapshot_set_hash),(r.latest_set_hash),(r.archive_set_hash),(r.contract_set_hash),(r.combined_set_hash)) h(v) WHERE r.module1_run_id=(SELECT run_id FROM _m2_1_vctx) AND (length(h.v)<>32 OR h.v !~ '^[0-9a-f]+$')))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_ctl.m2_1_strategy_contract_registry r CROSS JOIN LATERAL (VALUES(r.campaign_set_hash),(r.gate_definition_set_hash),(r.reason_code_set_hash),(r.outcome_definition_set_hash),(r.gate_result_set_hash),(r.routing_snapshot_set_hash),(r.latest_set_hash),(r.archive_set_hash),(r.contract_set_hash),(r.combined_set_hash)) h(v) WHERE r.module1_run_id=(SELECT run_id FROM _m2_1_vctx) AND (length(h.v)<>32 OR h.v !~ '^[0-9a-f]+$'))),false),'Registry hashes have valid shapes.');
