    PERFORM pg_temp.m2_1_add_check('M2_1_POS_102_COMBINED_SET_HASH','Combined set hash',((SELECT combined_set_hash FROM msbf_ctl.m2_1_strategy_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'RECONSTRUCTED',coalesce(((SELECT combined_set_hash=(SELECT md5(string_agg(entity_type||'|'||entity_key||'|'||row_hash,'|' ORDER BY entity_type,entity_key)) FROM _m2_1_vcanonical) FROM msbf_ctl.m2_1_strategy_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Combined canonical hash reconstructs.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_103_GENERATION_EVIDENCE','Generation evidence inventory',((SELECT count(*)::text FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND evidence_code IN ('M2_1_CAMPAIGN_ROW_COUNT','M2_1_GATE_DEFINITION_ROW_COUNT','M2_1_REASON_CODE_ROW_COUNT','M2_1_OUTCOME_DEFINITION_ROW_COUNT','M2_1_GATE_RESULT_ROW_COUNT','M2_1_ROUTING_SNAPSHOT_ROW_COUNT','M2_1_LATEST_ROW_COUNT','M2_1_ARCHIVE_ROW_COUNT','M2_1_COMPARISON_ROW_COUNT','M2_1_CANONICAL_ENTITY_COUNT','M2_1_CANONICAL_MISMATCH_COUNT','M2_1_CAMPAIGN_SET_HASH','M2_1_GATE_DEFINITION_SET_HASH','M2_1_REASON_CODE_SET_HASH','M2_1_OUTCOME_DEFINITION_SET_HASH','M2_1_GATE_RESULT_SET_HASH','M2_1_ROUTING_SNAPSHOT_SET_HASH','M2_1_COMBINED_SET_HASH')))::text,'18',coalesce(((SELECT count(*)=18 FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND evidence_code IN ('M2_1_CAMPAIGN_ROW_COUNT','M2_1_GATE_DEFINITION_ROW_COUNT','M2_1_REASON_CODE_ROW_COUNT','M2_1_OUTCOME_DEFINITION_ROW_COUNT','M2_1_GATE_RESULT_ROW_COUNT','M2_1_ROUTING_SNAPSHOT_ROW_COUNT','M2_1_LATEST_ROW_COUNT','M2_1_ARCHIVE_ROW_COUNT','M2_1_COMPARISON_ROW_COUNT','M2_1_CANONICAL_ENTITY_COUNT','M2_1_CANONICAL_MISMATCH_COUNT','M2_1_CAMPAIGN_SET_HASH','M2_1_GATE_DEFINITION_SET_HASH','M2_1_REASON_CODE_SET_HASH','M2_1_OUTCOME_DEFINITION_SET_HASH','M2_1_GATE_RESULT_SET_HASH','M2_1_ROUTING_SNAPSHOT_SET_HASH','M2_1_COMBINED_SET_HASH'))),false),'Exact generation evidence inventory is present.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_104_ZERO_CANONICAL_MISMATCH','Canonical mismatch evidence',((SELECT metric_value_numeric::text FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND evidence_code='M2_1_CANONICAL_MISMATCH_COUNT'))::text,'0',coalesce(((SELECT metric_value_numeric=0 FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND evidence_code='M2_1_CANONICAL_MISMATCH_COUNT')),false),'Generation recorded zero canonical mismatches.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_105_NO_PRICING_COLUMNS','No final pricing columns',((SELECT count(*)::text FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_policy_gate_result','application_eligibility_routing_snapshot','application_eligibility_routing_latest','application_eligibility_routing_archive') AND lower(column_name) IN ('apr','factor_rate','approved_amount','offer_amount','remittance_rate','offer_term','approved_term','final_price')))::text,'0',coalesce(((SELECT count(*)=0 FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_policy_gate_result','application_eligibility_routing_snapshot','application_eligibility_routing_latest','application_eligibility_routing_archive') AND lower(column_name) IN ('apr','factor_rate','approved_amount','offer_amount','remittance_rate','offer_term','approved_term','final_price'))),false),'Application-level M2.1 outputs do not create final pricing or offer terms.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_106_NO_ADVERSE_ACTION_COLUMNS','No production adverse-action output',((SELECT count(*)::text FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_policy_gate_result','application_eligibility_routing_snapshot','application_eligibility_routing_latest','application_eligibility_routing_archive') AND lower(column_name) IN ('adverse_action','adverse_action_code','adverse_action_notice','production_adverse_action_flag')))::text,'0',coalesce(((SELECT count(*)=0 FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_policy_gate_result','application_eligibility_routing_snapshot','application_eligibility_routing_latest','application_eligibility_routing_archive') AND lower(column_name) IN ('adverse_action','adverse_action_code','adverse_action_notice','production_adverse_action_flag'))),false),'Application-level M2.1 outputs contain no production adverse-action field; the governed reason dictionary flag is separately required to remain false.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_107_NO_FUNDED_OUTCOME','No funded outcome',((SELECT count(*)::text FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_policy_gate_result','application_eligibility_routing_snapshot','application_eligibility_routing_latest','application_eligibility_routing_archive') AND lower(column_name) IN ('funded','funded_flag','funded_outcome','funding_status','booking_probability','acceptance_probability')))::text,'0',coalesce(((SELECT count(*)=0 FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN ('application_policy_gate_result','application_eligibility_routing_snapshot','application_eligibility_routing_latest','application_eligibility_routing_archive') AND lower(column_name) IN ('funded','funded_flag','funded_outcome','funding_status','booking_probability','acceptance_probability'))),false),'Application-level M2.1 outputs contain no funded outcome or booking probability.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_108_NO_M2_2_TABLES','M2.2 stage boundary',((SELECT count(*)::text FROM information_schema.tables WHERE table_schema='msbf_m2' AND table_name LIKE 'm2_2%'))::text,'0',coalesce(((SELECT count(*)=0 FROM information_schema.tables WHERE table_schema='msbf_m2' AND table_name LIKE 'm2_2%')),false),'M2.2 objects do not exist.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_109_ZERO_BLOCKING_ERRORS','Blocking resolution errors',((SELECT count(*)::text FROM msbf_ctl.profile_resolution_error WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND severity='BLOCKING'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_ctl.profile_resolution_error WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND severity='BLOCKING')),false),'No blocking errors exist.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_110_G2_NO_MUTATION','G2 source cardinality preserved',((SELECT count(*)::text FROM msbf_m1.v_m1_17_g2_integrated_consumption WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'1500',coalesce(((SELECT count(*)=1500 FROM msbf_m1.v_m1_17_g2_integrated_consumption WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Accepted G2 source remains unchanged.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_111_M1_15_NO_MUTATION','M1.15 latest preserved',((SELECT count(*)::text FROM msbf_m1.application_module1_latest WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'1500',coalesce(((SELECT count(*)=1500 FROM msbf_m1.application_module1_latest WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Accepted M1.15 latest contract remains unchanged.');
    PERFORM pg_temp.m2_1_add_check('M2_1_POS_112_M1_16_NO_MUTATION','M1.16 latest preserved',((SELECT count(*)::text FROM msbf_m1.application_acquisition_contract_latest WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx)))::text,'750',coalesce(((SELECT count(*)=750 FROM msbf_m1.application_acquisition_contract_latest WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx))),false),'Accepted M1.16 acquisition contract remains unchanged.');
END;
$m2_1_checks$;

DO $m2_1_validation_inventory$
DECLARE v_total bigint;
BEGIN SELECT count(*) INTO v_total FROM _m2_1_validation;
 IF v_total<>112 THEN RAISE EXCEPTION 'M2.1 validation inventory expected 112; observed %.',v_total; END IF;
END;
$m2_1_validation_inventory$;

DELETE FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_1_vctx) AND evidence_code LIKE 'M2_1_POS_%';
INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_text,unit_code,status,interpretation)
SELECT (SELECT run_id FROM _m2_1_vctx),evidence_code,'PORTFOLIO',metric_name,observed_value,'VALIDATION',status,
       interpretation||' Threshold: '||coalesce(threshold_value,'<NULL>')
FROM _m2_1_validation;

DO $m2_1_validation_outcome$
DECLARE v_total bigint; v_pass bigint; v_fail bigint;
BEGIN
 SELECT count(*),count(*) FILTER(WHERE status='PASS'),count(*) FILTER(WHERE status='FAIL')
 INTO v_total,v_pass,v_fail FROM _m2_1_validation;
 IF v_total=112 AND v_pass=112 AND v_fail=0 THEN
  UPDATE msbf_ctl.m2_1_strategy_contract_registry SET contract_status='VALIDATED',validated_at=clock_timestamp()
  WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
  UPDATE msbf_ctl.run_registry SET run_status='M2_1_VALIDATED',notes=coalesce(notes,'')||' | M2.1 validation: 112 of 112 PASS.'
  WHERE run_id=(SELECT run_id FROM _m2_1_vctx);
 ELSE
  UPDATE msbf_ctl.m2_1_strategy_contract_registry SET contract_status='GENERATED',validated_at=NULL
  WHERE module1_run_id=(SELECT run_id FROM _m2_1_vctx);
  UPDATE msbf_ctl.run_registry SET run_status='M2_1_FAILED',notes=coalesce(notes,'')||format(' | M2.1 validation failed: %s PASS, %s FAIL.',v_pass,v_fail)
  WHERE run_id=(SELECT run_id FROM _m2_1_vctx);
 END IF;
END;
$m2_1_validation_outcome$;

COMMIT;
SELECT evidence_code,metric_name,observed_value,threshold_value,status,interpretation
FROM _m2_1_validation ORDER BY evidence_code;
